async function triggerLowStockAlert(params) {
	const { product, alertPhone, pushEnabled, smsEnabled, userId } = params;
	const message = `PRAN LOW STOCK ALERT: ${product.name} (${product.sku}) has only ${product.stock} ${product.unit}(s) left (Min: ${product.minStock}). Please restock immediately.`;
	if (pushEnabled) sendBrowserPushNotification(`Low Stock: ${product.name}`, message);
	let gatewaySent = false;
	let deliveryMethod = "push";
	let status = "logged";
	const cleanPhone = alertPhone.trim();
	if (smsEnabled && cleanPhone) {
		deliveryMethod = "mobile_sms";
		status = "queued";
		try {
			const res = await fetch("/api/send-sms", {
				method: "POST",
				headers: { "Content-Type": "application/json" },
				body: JSON.stringify({
					to: cleanPhone,
					message,
					productName: product.name,
					currentStock: product.stock
				})
			});
			if (res.ok) {
				if ((await res.json()).mode === "gateway") {
					gatewaySent = true;
					deliveryMethod = "gateway";
					status = "sent";
				}
			}
		} catch {}
	}
	if (cleanPhone || pushEnabled) try {
		await addDoc(collection(db, "smsAlerts"), {
			dealershipId: DEALERSHIP_ID,
			productId: product.id,
			productName: product.name.slice(0, 120),
			currentStock: product.stock,
			minStock: product.minStock,
			recipientPhone: (cleanPhone || "Browser Push").slice(0, 30),
			message: message.slice(0, 320),
			deliveryMethod,
			status,
			triggeredBy: userId,
			createdAt: serverTimestamp()
		});
	} catch (error) {
		handleFirestoreError(error, OperationType.CREATE, "smsAlerts");
	}
	return {
		smsDeepLink: cleanPhone ? buildSmsDeepLink(cleanPhone, message) : "",
		whatsappLink: cleanPhone ? buildWhatsAppLink(cleanPhone, message) : "",
		gatewaySent,
		message
	};
}
function exportSalesToCsv(sales, filename = "pran-daily-sales.csv") {
	const headers = [
		"Date",
		"Shop / Institution Name",
		"Address",
		"Phone",
		"Product",
		"Category",
		"Quantity",
		"Unit",
		"Unit Price (BDT)",
		"Total Amount (BDT)",
		"Paid Amount (BDT)",
		"Due Amount (BDT)",
		"Payment Status",
		"Recorded By"
	];
	const rows = sales.map((s) => [
		s.saleDate,
		`"${s.shopName.replace(/"/g, "\"\"")}"`,
		`"${s.shopAddress.replace(/"/g, "\"\"")}"`,
		`"${(s.shopPhone || "").replace(/"/g, "\"\"")}"`,
		`"${s.productName.replace(/"/g, "\"\"")}"`,
		s.category,
		s.quantity,
		s.unit,
		s.unitPrice,
		s.totalAmount,
		s.paidAmount,
		Math.max(0, s.totalAmount - s.paidAmount),
		s.paymentStatus.toUpperCase(),
		`"${s.recordedByName.replace(/"/g, "\"\"")}"`
	]);
	const csvContent = "data:text/csv;charset=utf-8," + [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
	const encodedUri = encodeURI(csvContent);
	const link = document.createElement("a");
	link.setAttribute("href", encodedUri);
	link.setAttribute("download", filename);
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
}
function exportInventoryToCsv(products, filename = "pran-inventory-stock.csv") {
	const headers = [
		"SKU",
		"Product Name",
		"Category",
		"Current Stock",
		"Min Threshold",
		"Unit",
		"Status",
		"Dealer Cost (BDT)",
		"Selling Price (BDT)",
		"Stock Value (BDT)"
	];
	const rows = products.map((p) => {
		const status = p.stock === 0 ? "OUT OF STOCK" : p.stock <= p.minStock ? "LOW STOCK" : "IN STOCK";
		return [
			p.sku,
			`"${p.name.replace(/"/g, "\"\"")}"`,
			p.category,
			p.stock,
			p.minStock,
			p.unit,
			status,
			p.costPrice,
			p.unitPrice,
			p.stock * p.unitPrice
		];
	});
	const csvContent = "data:text/csv;charset=utf-8," + [headers.join(","), ...rows.map((r) => r.join(","))].join("\n");
	const encodedUri = encodeURI(csvContent);
	const link = document.createElement("a");
	link.setAttribute("href", encodedUri);
	link.setAttribute("download", filename);
	document.body.appendChild(link);
	link.click();
	document.body.removeChild(link);
}
